function initTheme(){const t=document.getElementById("theme-toggle");t&&t.addEventListener("click",()=>{document.body.classList.toggle("light-theme");const e=document.body.classList.contains("light-theme");localStorage.setItem("theme",e?"light":"dark"),t.textContent=e?"☀️":"🌙"})}function initNavTabs(){const t=document.querySelectorAll(".pataliputra-tab-link");window.addEventListener("scroll",()=>{let e="";document.querySelectorAll(".pataliputra-section").forEach(t=>{const a=t.offsetTop-100;window.scrollY>=a&&(e=t.getAttribute("id"))}),t.forEach(t=>{t.classList.remove("active"),t.getAttribute("href")===`#${e}`&&t.classList.add("active")})})}function initBookmark(){const t=document.querySelector(".pataliputra-bookmark-btn");t&&t.addEventListener("click",()=>{const e="true"===t.getAttribute("aria-pressed");t.setAttribute("aria-pressed",!e),t.innerHTML=e?"♡ Save to Journey":"♥ Saved in Journey",t.style.background=e?"transparent":"var(--pataliputra-accent)",t.style.color=e?"var(--pataliputra-accent)":"#0f172a"})}document.addEventListener("DOMContentLoaded",()=>{initTheme(),initNavTabs(),initBookmark()});